head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입 시 부모 화면의 카테고리 목록을 selectbox 에 바인딩하고 FAQ 리스트를 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.parentWin = $p.parent();
        scwin.mainTabControl = scwin.parentWin.tac_faq;

        // selectbox에 바인딩 될 데이터 세팅(분류)
        const parentHelpClssList = scwin.parentWin.dlt_HelpClssList.getAllJSON();
        dlt_HelpClssList.setJSON(parentHelpClssList);

        // FAQ 리스트
        if(scwin.mainTabControl) {
            scwin.searchFaqList();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL16300_TAB1.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/// EVENT ///

/**
 * @method
 * @name btn_search_onclick
 * @description 조회 버튼 클릭 — FAQ 리스트 조회(검색)를 실행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_search_onclick(e);
 */
scwin.btn_search_onclick = function (e) {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL16300_TAB1.btn_search_onclick" });
    }
};

/**
 * @method
 * @name btn_print_onclick
 * @description 인쇄 버튼 클릭 — 조회한 내역을 브라우저 인쇄로 출력한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_print_onclick(e);
 */
scwin.btn_print_onclick = function (e) {
    try {
        window.print();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL16300_TAB1.btn_print_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/// SUBMISSION ///

/**
 * @method
 * @name sbm_SelectFaqList_submitdone
 * @description FAQ 리스트 조회 성공 콜백 — 선택 탭이 애로사항(0100000025)이면 타이틀을 포함하여 본문을 생성한다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_SelectFaqList_submitdone(sbmRtn);
 */
scwin.sbm_SelectFaqList_submitdone = function (e) {
    let isTitle = false;

    const tabId = scwin.mainTabControl.getSelectedTabID();
    if(tabId === "0100000025") { // 예외 - 애로사항 (타이틀 포함한 결과)
        isTitle = true;
    }

    scwin.makeContent(isTitle);
};

/// FUNCTION ///

/**
 * @method
 * @name searchFaqList
 * @description FAQ 리스트 조회 — 로그인 전, 후 구분하여 조회한다.
 *              1.화면 첫 진입 2.탭 선택하여 로드 3.(카테고리 선택 + 키워드미입력) 조회버튼으로 로드
 * @returns {void}
 * @hidden N
 * @example await scwin.searchFaqList();
 */
scwin.searchFaqList = async function () {
    const searchParam = scwin.parentWin.scwin.searchParamData;
    if(!searchParam) {
        // 1.화면 첫 진입
        const tabId = scwin.mainTabControl.getSelectedTabID();
        dma_SearchReq.setJSON({
            "helpClssId" : tabId,
            "keyword" : ""
        });
    } else {
        // 2,3
        dma_SearchReq.setJSON({
            "helpClssId" : searchParam.helpClssId,
            "keyword" : searchParam.keyword
        });
    }

    if(scwin.parentWin.scwin.isLogin) {
        const sbmOptions = {
            id : "sbm_SelectAfLoginFaqList",
            action : "/api/discls/support/faq/select-list",
            method : "get",
            ref : "dma_SearchReq",
            target : "dlt_FaqList=body",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_SelectFaqList_submitdone(sbmRtn);
    } else {
        const sbmOptions = {
            id : "sbm_SelectBfLoginFaqList",
            action : "/api/discls/guest/help/faq/select-list",
            method : "get",
            ref : "dma_SearchReq",
            target : "dlt_FaqList=body",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_SelectFaqList_submitdone(sbmRtn);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description FAQ 리스트 조회(검색) — 검색 파라미터를 부모 화면에 저장한 뒤 해당 분류 탭(미선택 시 전체조회 hidden 탭)을 재로드/선택한다.
 * @returns {void}
 * @hidden N
 * @example scwin.search();
 */
scwin.search = function () {
    const helpClssId = sel_helpClssId.getValue();
    const keyword = ipt_keyword.getValue();
    const searchReq = {
        "helpClssId" : helpClssId,
        "keyword" : keyword
    };
    scwin.parentWin.scwin.searchParamData = searchReq;

    let tabIndex = "";
    if(helpClssId) {
        // 분류 tab
        tabIndex = scwin.mainTabControl.getTabIndex(helpClssId);

    } else {
        // 전체조회 tab(hidden)
        tabIndex = scwin.mainTabControl.getTabIndex("tabs_search");
    }

    const wFrame = scwin.mainTabControl.getFrame(tabIndex);
    const tabSrc = wFrame.getSrc();
    wFrame.setSrc(tabSrc);
    scwin.mainTabControl.setSelectedTabIndex(tabIndex);
};

/**
 * @method
 * @name makeContent
 * @description 탭 본문 내용 생성 — 조회 결과로 분류 타이틀·아코디언(질문/답변)을 동적 생성한다.
 * @param {Boolean} isTitle 타이틀 포함 여부
 * @returns {void}
 * @hidden N
 * @example scwin.makeContent(true);
 */
scwin.makeContent = function (isTitle) {
    const plugin = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';
    const resList = dlt_FaqList.getAllJSON();

    if(!scwin.isEmptyData(resList, isTitle)) {

        for (let j = 0; j < resList.length; j++) {
            const mData = resList[j];
            const faqDtlList = mData.faqDtlList;

            // 분류 타이틀 Append
            if(isTitle) {
                if(faqDtlList.length > 0) {
                    const pathXml = [];
                    pathXml.push('<xf:group class="titbox" id="grp_tit_path_'+j+'" style="background-color:#EAF7FF; margin:0px; padding:8px 0px;" '+plugin+'>');
                    pathXml.push('</xf:group>');
                    $p.dynamicCreate("grp_tit_path_"+j, "group", pathXml.join(""), grp_faq);

                    const path = mData.helpClssNm;
                    $p.dynamicCreate("txt_tit_path_"+j, "textbox", '<w2:textbox id="txt_tit_path_'+j+'" label="'+path+'" style="" tagname="h3" '+plugin+'></w2:textbox>', $p.getComponentById("grp_tit_path_"+j));
                }
            }

            // 아코디언 Append
            if(faqDtlList.length > 0) {
                const compXml = [];
                compXml.push('<w2:accordion class="acd" collapseAll="true" collapsible="true" id="acd_faq_'+j+'" independentPanel="true" metaev_onclick_desc="상세내용을 하단에 출력" metaev_onclick_name="제목" style="" '+plugin+'>');
                for (let i = 0; i < faqDtlList.length; i++) {
                    const item = faqDtlList[i];
                    compXml.push('<w2:panels style="" id="panels_'+j+'_'+i+'" class="">');

                    // 질문내용
                    compXml.push('  <w2:panelTitle class="" id="panelTitle_'+j+'_'+i+'" label="' + item.quesContn + '" style=""></w2:panelTitle>');

                    // 답변내용
                    compXml.push('  <w2:panelContent class="" id="panelContent_'+j+'_'+i+'" style="">');
                    compXml.push('      <xf:group id="grp_ansContn_'+j+'_'+i+'" style="" tagname="pre">');
                    compXml.push('      </xf:group>');
                    compXml.push('  </w2:panelContent>');

                    compXml.push('</w2:panels>');
                }
                compXml.push('</w2:accordion>');

                $p.dynamicCreate("acd_faq_"+j, "accordion", compXml.join(""), grp_faq);

                // grp_ansContn에 HTML 데이터 세팅
                // TODO: $p.dynamicCreate 로 생성한 아코디언 내부 DOM 렌더 완료 대기용 임의 지연(50ms) — code-convention 위반.
                //       렌더 완료 이벤트/콜백 기반으로 재작성이 필요하나 dynamicCreate 완료 시점 훅 부재로 동작 변경 위험이 있어 현행 유지.
                setTimeout(function () {
                    for (let i = 0; i < faqDtlList.length; i++) {
                        const item = faqDtlList[i];
                        const realId = $p.getComponentById("grp_ansContn_"+j+"_"+i).getID();
                        const grpAnsContn = document.getElementById(realId);
                        grpAnsContn.insertAdjacentHTML("beforeend", item.ansContn);
                    }
                }, 50);
            }
        }
    } else {
        scwin.makeContentEmpty();
    }

};

/**
 * @method
 * @name makeContentEmpty
 * @description 탭 본문 내용 생성 — 데이터 없음. "검색된 FAQ가 없습니다." 안내 텍스트박스를 동적 생성한다.
 * @returns {void}
 * @hidden N
 * @example scwin.makeContentEmpty();
 */
scwin.makeContentEmpty = function() {
    const message = "검색된 FAQ가 없습니다.";
    const plugin = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';
    $p.dynamicCreate("no-data-list", "textbox", '<w2:textbox '+plugin+' id="no-data-list" label="'+message+'" style="width:100%; padding:20px 0; background-color:#eaf7ff; text-align:center;"></w2:textbox>', grp_faq);
};

/**
 * @method
 * @name isEmptyData
 * @description 조회 데이터 존재 여부 — clssLevel 2의 faqDtlList(질문답변 리스트)가 모두 비어있는지 확인한다.
 *              1. 분류 단일 조회일 경우, clssLevel 1만 존재
 *              2. 전체 조회일 경우, clssLevel 1은 분류, 2는 1의 하위 문답 데이터
 * @param {Array} resList FAQ조회 응답 데이터
 * @param {Boolean} isTitle 타이틀 포함 여부(타이틀을 포함하는 데이터의 경우 clssLevel 2에 데이터 존재)
 * @returns {Boolean} 빈 데이터 여부
 * @hidden N
 * @example const isEmpty = scwin.isEmptyData(resList, true);
 */
scwin.isEmptyData = function(resList, isTitle) {
    let isEmpty = true;
    for (let i = 0; i < resList.length; i++) {
        const bodyData = resList[i];
        if(isTitle) {
            if(bodyData.clssLevel > 1 && bodyData.faqDtlList.length > 0) {
                isEmpty = false;
            }
        }else {
            if(bodyData.faqDtlList.length > 0) {
                isEmpty = false;
            }
        }
    }
    return isEmpty;
};
